Per_Exec_Wake timeout_q_looping( void )
{
    #define TIMEOUT_Q_OBJ (((Timeout_Q_Node*)curr)->timeout_q_obj)
    
    Per_Exec_Wake wake_state = PER_EXEC_SLEEP ; 

	Fifo_Node *curr , *temp ;
	
	for( curr = timeout_q_fifo_exec->rhs ; curr != timeout_q_fifo_exec ; curr = curr->rhs )
	{
		if( (TIMEOUT_Q_OBJ.req_done) || out_exec( NULL , (Out)(&TIMEOUT_Q_OBJ))      )
		{
			TIMEOUT_Q_OBJ.req_done = FALSE ; 
													
			temp = curr->rhs ; 
			
			fifo_unlink( curr ) ; 

			fifo_insert( timeout_q_fifo_free , curr ) ; 
			
			curr = temp->lhs ; 
		}
		else
		{
			wake_state = PER_EXEC_WAKE ; 
		}
	}	
	
	return wake_state ; 

    #undef TIMEOUT_Q_OBJ
}
        
